const contracts = $input.all()[0].json;
// Split by days until expiry
const buckets = { 30: [], 15: [], 7: [], 3: [], 1: [] };
for (const c of contracts) {
  const days = c.days_until_expiry;
  if (buckets[days]) buckets[days].push(c);
}
const items = [];
for (const [d, list] of Object.entries(buckets)) {
  for (const c of list) {
    items.push({
      ...c,
      reminder_bucket: parseInt(d),
      sequence_step: d === '30' ? 'first_notice' : d === '15' ? 'value_reminder' : d === '7' ? 'urgency' : d === '3' ? 'final_call' : 'last_chance'
    });
  }
}
return items;

const contract = $input.first().json;
const usage = $input.all()[1]?.json || { sessions: 0, features_used: [], mrr: 0 };

// Health score 0-100
let health = 50;
if (usage.sessions > 1000) health += 20;
if (usage.features_used?.length > 5) health += 15;
if (contract.days_until_expiry <= 7) health -= 15;
if (contract.payment_history?.late_count > 2) health -= 25;

let tier = 'yellow';
if (health >= 75) tier = 'green';
else if (health <= 40) tier = 'red';

return {
  ...contract,
  usage,
  health_score: Math.max(0, Math.min(100, health)),
  tier,
  features_underused: usage.features_used?.length < 3 ? true : false
};
